import { useState } from 'react';
import './dropdown.css';
export function Dropdown({ items }: { items: string[] }) {
  const [open, setOpen] = useState(false);
  return (
    <div className="dropdown">
      <button onClick={() => setOpen(o => !o)}>Menu</button>
      {open && <ul className="dropdown-menu">{items.map(i => <li key={i}>{i}</li>)}</ul>}
    </div>
  );
}

