import { useState } from 'react';
type Contact = { id: string; name: string; email: string };
function Row({ c, onSelect }: { c: Contact; onSelect: (id: string) => void }) {
  return <li onClick={() => onSelect(c.id)}>{c.name} — {c.email}</li>;
}
export function ContactList({ contacts }: { contacts: Contact[] }) {
  const [q, setQ] = useState('');
  const [selected, setSelected] = useState<string | null>(null);
  const filtered = contacts.filter(c => c.name.toLowerCase().includes(q.toLowerCase()));
  return (
    <div>
      <input value={q} onChange={e => setQ(e.target.value)} />
      <ul>{filtered.map(c => <Row key={c.id} c={c} onSelect={(id) => setSelected(id)} />)}</ul>
      {selected && <p>Selected {selected}</p>}
    </div>
  );
}
